import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Timeout Is Not Failure","description":"Why network timeouts must never trigger naive payment retries, and how AgentPay eliminates double charges.","frontmatter":{"title":"Timeout Is Not Failure","description":"Why network timeouts must never trigger naive payment retries, and how AgentPay eliminates double charges."},"headers":[],"relativePath":"learn/04-agentpay-concepts/timeout-is-not-failure.md","filePath":"learn/04-agentpay-concepts/timeout-is-not-failure.md","lastUpdated":1792490239000}'),i={name:"learn/04-agentpay-concepts/timeout-is-not-failure.md"};function r(l,e,o,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="timeout-is-not-failure" tabindex="-1">Timeout Is Not Failure <a class="header-anchor" href="#timeout-is-not-failure" aria-label="Permalink to &quot;Timeout Is Not Failure&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay has not undergone an independent security audit. Do not use with production funds. All examples on this page are based on testnets and test tokens.</p></div><h2 id="in-a-nutshell" tabindex="-1">In a Nutshell <a class="header-anchor" href="#in-a-nutshell" aria-label="Permalink to &quot;In a Nutshell&quot;">​</a></h2><p><strong>A timeout merely indicates that you did not receive a response; it never proves that the event did not occur.</strong> In financial systems, timeouts must trigger state verification before any corrective action—never naive retries.</p><h2 id="a-concrete-scenario" tabindex="-1">A Concrete Scenario <a class="header-anchor" href="#a-concrete-scenario" aria-label="Permalink to &quot;A Concrete Scenario&quot;">​</a></h2><p>Consider our research agent querying a market data API priced at $0.10 USDC (<code>100_000</code> atomic units):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Agent queries endpoint            → Receives HTTP 402 &quot;Payment Required&quot;</span></span>
<span class="line"><span>2. Agent signs auth &amp; re-requests     → Payment submitted</span></span>
<span class="line"><span>3. On-chain settlement succeeds       ✅</span></span>
<span class="line"><span>4. Seller processes request and prepares payload</span></span>
<span class="line"><span>5. Response drops in network / Seller times out ⏱️</span></span>
<span class="line"><span>6. Agent receives a Client Timeout error</span></span></code></pre></div><p>The agent observes a timeout. Conventional retry logic concludes: &quot;Request failed, try again&quot;:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>7. Agent sends request again, signs new payment</span></span>
<span class="line"><span>8. Second transaction also succeeds   ✅</span></span></code></pre></div><p>The outcome: <strong>the agent was billed twice for a service that was fulfilled once.</strong> This is the classic Double Charge trap.</p><p>The root cause stems from a false equation:</p><blockquote><p>❌ Timeout = Failure → Safe to Retry</p></blockquote><h2 id="deconstructing-the-failure" tabindex="-1">Deconstructing the Failure <a class="header-anchor" href="#deconstructing-the-failure" aria-label="Permalink to &quot;Deconstructing the Failure&quot;">​</a></h2><p>A payment flow comprises three decoupled phases occurring across independent systems:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Question Answered</th></tr></thead><tbody><tr><td><strong>Payment Intent</strong></td><td>Was the payment proposal accepted and is the authorization valid?</td></tr><tr><td><strong>Fund Settlement</strong></td><td>Were funds actually debited (on-chain tx confirmed, or platform wallet held)?</td></tr><tr><td><strong>Service Fulfillment</strong></td><td>Did the seller&#39;s upstream service execute and return payload?</td></tr></tbody></table><p>Because these phases run asynchronously, timeouts can occur at any interface:</p><ul><li>Funds were deducted, but the HTTP response dropped in transit.</li><li>The request reached upstream, but upstream is still computing.</li><li>The transaction was broadcast, but on-chain receipt confirmation timed out.</li></ul><p>In each scenario, <strong>&quot;no response received&quot; maps to completely different underlying system states.</strong> Treating them all as &quot;failure&quot; inevitably corrupts ledgers.</p><h2 id="flawed-approaches-and-why-they-fail" tabindex="-1">Flawed Approaches and Why They Fail <a class="header-anchor" href="#flawed-approaches-and-why-they-fail" aria-label="Permalink to &quot;Flawed Approaches and Why They Fail&quot;">​</a></h2><h3 id="approach-1-treat-timeout-as-failure-and-retry-with-a-fresh-signature" tabindex="-1">Approach 1: Treat Timeout as Failure and Retry with a Fresh Signature <a class="header-anchor" href="#approach-1-treat-timeout-as-failure-and-retry-with-a-fresh-signature" aria-label="Permalink to &quot;Approach 1: Treat Timeout as Failure and Retry with a Fresh Signature&quot;">​</a></h3><p>Described above. Every new signature is a legally valid authorization on-chain, and each submission executes another debit.</p><h3 id="approach-2-treat-timeout-as-success" tabindex="-1">Approach 2: Treat Timeout as Success <a class="header-anchor" href="#approach-2-treat-timeout-as-success" aria-label="Permalink to &quot;Approach 2: Treat Timeout as Success&quot;">​</a></h3><p>Equally disastrous. If the request was dropped before reaching the seller, the buyer marked it paid and received nothing.</p><h3 id="approach-3-release-budget-immediately-on-timeout" tabindex="-1">Approach 3: Release Budget Immediately on Timeout <a class="header-anchor" href="#approach-3-release-budget-immediately-on-timeout" aria-label="Permalink to &quot;Approach 3: Release Budget Immediately on Timeout&quot;">​</a></h3><p>Suppose the client holds quota for this transaction. Once an EIP-3009 or transaction signature is broadcast, <strong>the seller or relayer can still submit it on-chain prior to expiration</strong>. Releasing the budget prematurely allows the agent to spend the same money twice:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reserve 0.1 → Signature sent → Timeout → Release quota → Agent spends 0.1</span></span>
<span class="line"><span>                                                               ↑</span></span>
<span class="line"><span>                     Original signature mined on-chain, total spend: 0.2</span></span></code></pre></div><h3 id="approach-4-infinite-unbounded-retries" tabindex="-1">Approach 4: Infinite Unbounded Retries <a class="header-anchor" href="#approach-4-infinite-unbounded-retries" aria-label="Permalink to &quot;Approach 4: Infinite Unbounded Retries&quot;">​</a></h3><p>Unchecked retry storms during upstream outages amplify system load and multiply double-charge exposure.</p><h2 id="the-agentpay-approach" tabindex="-1">The AgentPay Approach <a class="header-anchor" href="#the-agentpay-approach" aria-label="Permalink to &quot;The AgentPay Approach&quot;">​</a></h2><p>The core tenet: <strong>&quot;Result Unknown&quot; is an explicit, first-class state, not an error.</strong> In this state, the system permits query and reconciliation—never blind payment re-submissions.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>           Timeout / Exception</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    ▼</span></span>
<span class="line"><span>       Result Unknown (First-Class State)</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>       ┌────────────┴────────────┐</span></span>
<span class="line"><span>       ▼                         ▼</span></span>
<span class="line"><span>Query Underlying State    Blind Retries Prohibited</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>  ┌────┼──────────────┐</span></span>
<span class="line"><span>  ▼    ▼              ▼</span></span>
<span class="line"><span>Settled Confirmed Void  Still Indeterminate</span></span>
<span class="line"><span>  │    │              │</span></span>
<span class="line"><span>Proceed Safe Quota    Maintain Lock,</span></span>
<span class="line"><span>       Release        Flag for Reconciliation</span></span></code></pre></div><p>Four fundamental rules govern this model:</p><p><strong>1. Once a signature is dispatched, budget is never released immediately due to network drops.</strong><br> Two criteria must be simultaneously satisfied before releasing the reservation: the authorization has expired (plus a safety buffer margin), and verifiable confirmation confirms it was never mined on-chain.</p><p><strong>2. When settlement outcome is unknown, blind re-submission is strictly forbidden.</strong><br> If settlement is in-flight or indeterminate, the gateway queries receipts and reconciles state without creating new authorizations.</p><p><strong>3. Idempotency keys prevent duplicate billing.</strong><br> The client attaches an immutable <code>Idempotency-Key</code> to every distinct business action. When the gateway detects an identical key, it performs a <strong>Free Replay</strong>, returning existing cached results or reusing active holds without additional charges. If the same key is supplied with differing payloads, it is rejected immediately as a tampering attempt.</p><p><strong>4. Payment settlement and service fulfillment are tracked independently.</strong><br> When on-chain settlement succeeds but upstream fulfillment fails, AgentPay records <code>Settled / Fulfillment Pending</code>, granting free fulfillment retries rather than writing off the transaction as lost.</p><h3 id="platform-virtual-wallet-behavior" tabindex="-1">Platform Virtual Wallet Behavior <a class="header-anchor" href="#platform-virtual-wallet-behavior" aria-label="Permalink to &quot;Platform Virtual Wallet Behavior&quot;">​</a></h3><p>On the gateway virtual wallet path, the lifecycle is <code>Hold → Upstream Call → Capture or Release</code>:</p><table tabindex="0"><thead><tr><th>Upstream Status</th><th>Gateway Behavior</th></tr></thead><tbody><tr><td>Success (2xx)</td><td><strong>Capture</strong>: Confirm hold into irrevocable deduction</td></tr><tr><td>Client Error (4xx)</td><td><strong>Release</strong>: Release hold immediately without charge</td></tr><tr><td>Server Error (5xx) / Timeout</td><td><strong>Maintain Hold</strong>: Neither capture nor release; preserve hold pending reconciliation</td></tr></tbody></table><p>5xx errors and timeouts cannot be released blindly because upstream may have partially or fully executed the work. Preserving the hold is the conservative choice: funds are temporarily unavailable, but neither overbilled nor leaked. Holds carry TTLs and are safely reclaimed by background workers.</p><h3 id="client-side-best-practice" tabindex="-1">Client-Side Best Practice <a class="header-anchor" href="#client-side-best-practice" aria-label="Permalink to &quot;Client-Side Best Practice&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">headers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;Idempotency-Key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order-20261020-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Fixed per business action</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.get(url, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">headers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">headers, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">except</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.TimeoutException:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Retry with the exact same Idempotency-Key: zero duplicate charge</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.get(url, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">headers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">headers, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The golden rule: <strong>Always reuse the same Idempotency-Key when retrying an operation.</strong> Generating a random UUID per retry informs the gateway that each attempt is a new, chargeable transaction.</p><h2 id="the-replay-resolving-the-opening-scenario" tabindex="-1">The Replay: Resolving the Opening Scenario <a class="header-anchor" href="#the-replay-resolving-the-opening-scenario" aria-label="Permalink to &quot;The Replay: Resolving the Opening Scenario&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Agent pays &amp; requests, seller captures payment</span></span>
<span class="line"><span>2. Response drops in network, agent catches timeout</span></span>
<span class="line"><span>3. Agent retries using the exact same Idempotency-Key</span></span>
<span class="line"><span>4. Gateway identifies existing transaction → Returns cached response without re-charging</span></span></code></pre></div><p>Result: Single debit, zero double billing, payload safely delivered.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><p><strong>Q: Why doesn&#39;t the system just wait until certainty is achieved?</strong><br> Blockchain block confirmation and upstream latencies are unpredictable. Indefinite synchronous blocking degrades agent performance and exhausts connection pools. The system returns &quot;Processing / Indeterminate&quot; and completes reconciliation asynchronously.</p><p><strong>Q: How should idempotency keys be generated?</strong><br> Derive them deterministically from the business context: e.g., <code>task_id + step_number</code>. All retries for that step share the key; distinct steps use distinct keys.</p><p><strong>Q: Does maintaining holds lock up working capital indefinitely?</strong><br> No. Holds carry a strict TTL. Once expired without capture, background sweepers release the reservation or escalate to admin console alerts.</p><p><strong>Q: Does this guarantee 100% prevention of double debits?</strong><br> These mechanics substantially eliminate duplicate billing under standard network faults, validated across extensive fault-injection suites (upstream 5xx, network drops, crash recovery). However, AgentPay remains experimental open-source software and has not undergone third-party auditing.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Understand concurrency budget holds: <a href="./budget-reservation">Budget Reservation</a></li><li>Learn why state must decouple intent, settlement, and fulfillment: <a href="./three-state-model">Three-State Model</a></li><li>Inspect payment traces under failure: <a href="./../05-hands-on/read-payment-trace">Read Payment Trace</a></li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li><a href="/docs/specs/state-machine">Unified Payment State Machine</a>: State transitions and recovery workflows</li><li><a href="/docs/specs/protocol-consistency">Protocol Consistency Specification</a>: Idempotency contracts and error codes</li><li><a href="/docs/specs/wallet-ledger">Wallet &amp; Ledger Specification</a>: Hold, capture, release rules</li><li><a href="/docs/specs/threat-model-v1">Threat Model v1</a>: Hold leakage and replay threat analysis</li></ul>`,55)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
